/*! AutoList Pro QRCode shim | Public Domain | Simple wrapper that renders a QR using a remote image generator. */
(function(root){
  function QRCode(el, options){
    this._el = (typeof el==='string')?document.getElementById(el):el;
    this._options = options || {};
    this.makeCode(this._options.text || '');
  }
  QRCode.prototype.makeCode = function(text){
    var size = this._options.width || 160;
    var url = 'https://api.qrserver.com/v1/create-qr-code/?size=' + size + 'x' + size + '&data=' + encodeURIComponent(String(text||''));
    var img = new Image();
    img.width = size; img.height = size; img.alt = 'QR'; img.decoding = 'async'; img.referrerPolicy = 'no-referrer';
    img.src = url;
    while(this._el.firstChild) this._el.removeChild(this._el.firstChild);
    this._el.appendChild(img);
  };
  root.QRCode = QRCode;
})(this);
